function validate([equation]) {
  if (typeof equation !== 'string' || equation.length < 3 || equation.length > 1000) return 'equation must have 3 to 1000 characters.';
  const parts = equation.split('=');
  if (parts.length !== 2) return 'equation needs exactly one "=".';
  const term = '(?:(?:0|[1-9]\\d*)?x|0|[1-9]\\d*)';
  const shape = new RegExp('^[+-]?' + term + '(?:[+-]' + term + ')*$');
  if (!shape.test(parts[0]) || !shape.test(parts[1])) return 'Each side must be terms like 3x, x or 7 joined by + and -.';
  if ((equation.match(/\d+/g) || []).some(d => Number(d) > 100)) return 'Every number is at most 100.';
  let coefficient = 0;
  let constant = 0;
  parts.forEach((part, index) => {
    const side = index === 0 ? 1 : -1;
    for (const token of part.match(/[+-]?(\d*x|\d+)/g)) {
      const sign = token[0] === '-' ? -side : side;
      const body = token.replace(/^[+-]/, '');
      if (body.endsWith('x')) coefficient += sign * (body === 'x' ? 1 : Number(body.slice(0, -1)));
      else constant -= sign * Number(body);
    }
  });
  if (coefficient !== 0 && constant % coefficient !== 0) return 'A single solution must be an integer.';
  return null;
}

