function solveEquation(equation) {
  let coefficient = 0;
  let constant = 0;
  let side = 1;
  let i = 0;

  while (i < equation.length) {
    if (equation[i] === '=') {
      side = -1;
      i++;
      continue;
    }
    let sign = side;
    if (equation[i] === '+' || equation[i] === '-') {
      if (equation[i] === '-') sign = -sign;
      i++;
    }
    let digits = '';
    while (i < equation.length && equation[i] >= '0' && equation[i] <= '9') {
      digits += equation[i];
      i++;
    }
    if (equation[i] === 'x') {
      coefficient += sign * (digits === '' ? 1 : Number(digits));
      i++;
    } else {
      constant -= sign * Number(digits);
    }
  }

  if (coefficient === 0) {
    return constant === 0 ? 'Infinite solutions' : 'No solution';
  }
  return 'x=' + constant / coefficient;
}

