function solveEquation(equation) {
  // Evaluate left - right at every integer that could be the answer and count the roots.
  const sides = equation.split('=').map(part => part.match(/[+-]?(\d*x|\d+)/g));
  const evaluate = (tokens, t) => {
    let total = 0;
    for (const token of tokens) {
      if (token.endsWith('x')) {
        const head = token.slice(0, -1);
        const factor = head === '' || head === '+' ? 1 : head === '-' ? -1 : Number(head);
        total += factor * t;
      } else {
        total += Number(token);
      }
    }
    return total;
  };
  const numbers = equation.match(/\d+/g) || [];
  const bound = numbers.reduce((sum, d) => sum + Number(d), 0) + 1;
  const roots = [];
  for (let t = -bound; t <= bound && roots.length < 2; t++) {
    if (evaluate(sides[0], t) === evaluate(sides[1], t)) roots.push(t);
  }
  if (roots.length === 2) return 'Infinite solutions';
  if (roots.length === 1) return 'x=' + roots[0];
  return 'No solution';
}

