function generate(rand, size) {
  const large = size === 'large';
  const maxValue = large ? 100 : (rand() < 0.5 ? 5 : 12);
  const randInt = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  for (;;) {
    // Each term: { left, sign, isX, value }. C·x = K collects everything on the left.
    const terms = [];
    const perSide = large ? randInt(60, 110) : randInt(1, 3);
    for (const left of [true, false]) {
      const count = large ? perSide + randInt(-20, 20) : randInt(1, 3);
      for (let k = 0; k < count; k++) terms.push({ left, sign: rand() < 0.5 ? 1 : -1, isX: rand() < 0.45, value: randInt(0, maxValue) });
    }
    const totals = () => {
      let C = 0, K = 0;
      for (const t of terms) {
        const s = (t.left ? 1 : -1) * t.sign;
        if (t.isX) C += s * t.value; else K -= s * t.value;
      }
      return [C, K];
    };
    const insert = (term) => {
      const position = randInt(0, terms.length);
      terms.splice(position, 0, term);
    };
    const mode = rand();
    let [C, K] = totals();
    if (mode < 0.4) {
      // No unique answer: cancel the x coefficient.
      while (C !== 0) {
        const v = Math.min(Math.abs(C), maxValue);
        insert({ left: true, sign: C > 0 ? -1 : 1, isX: true, value: v });
        [C, K] = totals();
      }
      if (mode < 0.2) {
        while (K !== 0) {
          const v = Math.min(Math.abs(K), maxValue);
          insert({ left: true, sign: K > 0 ? 1 : -1, isX: false, value: v });
          [C, K] = totals();
        }
      } else if (K === 0) {
        insert({ left: false, sign: 1, isX: false, value: randInt(1, maxValue) });
      }
    } else {
      if (C === 0) insert({ left: rand() < 0.5, sign: rand() < 0.5 ? 1 : -1, isX: true, value: randInt(1, maxValue) });
      [C, K] = totals();
      if (C === 0) continue;
      const target = Math.round(K / C) + randInt(-2, 2);
      let diff = C * target - K;
      while (diff !== 0) {
        const v = Math.min(Math.abs(diff), maxValue);
        insert({ left: true, sign: diff > 0 ? -1 : 1, isX: false, value: v });
        [C, K] = totals();
        diff = C * target - K;
      }
    }
    const render = (list) => list.map((t, k) => {
      const body = t.isX ? (t.value === 1 && rand() < 0.9 ? 'x' : t.value + 'x') : String(t.value);
      if (t.sign < 0) return '-' + body;
      return k === 0 ? body : '+' + body;
    }).join('');
    const leftTerms = terms.filter(t => t.left);
    const rightTerms = terms.filter(t => !t.left);
    if (leftTerms.length === 0 || rightTerms.length === 0) continue;
    const equation = render(leftTerms) + '=' + render(rightTerms);
    if (equation.length >= 3 && equation.length <= 1000) return [equation];
  }
}
